@startuml

class Center {
  + Name
  + Address
}

class Room {
  + Number
  + MaxCapacity
}

class Person {
  + FirstName
  + FamilyName
  + BirthDate
}

class Trainer {
  + Diploma
}

abstract class Session {
  + Date
  + StartHour
}

class GroupSession extends Session {
  + Type
}

class IndividualSession extends Session {
}

Person "1" -- "*" Room : occupies
Center "1" *-- "1..*" Room
Center "1" -- "*" Session

Room "1" -- "*" Session

Person "1" -- "*" Session : participant

Trainer "0..1" -- "*" GroupSession : supervises

@enduml

